import xml.etree.ElementTree as ET
tree = ET.parse('/work/output/artifacts/skill-bpmn-edit-group-to-subflow/Fulfillment.bpmn')
root = tree.getroot()

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

# Collect all IDs in the document
all_ids = set()
for el in root.iter():
    eid = el.get('id')
    if eid:
        all_ids.add(eid)

print('All IDs:', sorted(all_ids))

# Check all refs resolve
errors = []
ref_attrs = ['sourceRef','targetRef','attachedToRef','bpmnElement','default']
for el in root.iter():
    for attr in ref_attrs:
        val = el.get(attr)
        if val and val not in all_ids:
            errors.append(f'UNRESOLVED {attr}={val} in <{el.tag}>')

# Check subprocess has start/end
sp = root.find('.//bpmn:subProcess', NS)
if sp is not None:
    sub_start = sp.findall('bpmn:startEvent', NS)
    sub_end = sp.findall('bpmn:endEvent', NS)
    print(f'SubProcess start events: {len(sub_start)}, end events: {len(sub_end)}')

# Check every flow element has a BPMNShape
diagram = root.find('.//bpmndi:BPMNDiagram', NS)
shapes = set()
edges = set()
for shape in root.iter('{http://www.omg.org/spec/BPMN/20100524/DI}BPMNShape'):
    shapes.add(shape.get('bpmnElement'))
for edge in root.iter('{http://www.omg.org/spec/BPMN/20100524/DI}BPMNEdge'):
    edges.add(edge.get('bpmnElement'))

print('Shapes:', sorted(shapes))
print('Edges:', sorted(edges))

# Find all flow nodes that need shapes
flow_nodes = []
for tag in ['startEvent','endEvent','scriptTask','subProcess','exclusiveGateway','parallelGateway']:
    for el in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}'+tag):
        eid = el.get('id')
        if eid:
            flow_nodes.append(eid)
            if eid not in shapes:
                errors.append(f'MISSING SHAPE for {eid}')

# Find all sequence flows needing edges
for sf in root.iter('{http://www.omg.org/spec/BPMN/20100524/MODEL}sequenceFlow'):
    eid = sf.get('id')
    if eid and eid not in edges:
        errors.append(f'MISSING EDGE for flow {eid}')

if errors:
    for e in errors:
        print('ERROR:', e)
else:
    print('STRUCTURAL CHECK: PASSED')
"

